        public Version Version
        {
            get => version;
            private set
            {
                version = value;
                CanInvokeMultipleCmd = version >= new Version(1, 7);
            }
        }

        public bool CanInvokeMultipleCmd { get; private set; }

        public async Task<bool> Ping()
        {
            //try
